#Requires -RunAsAdministrator
[CmdletBinding()]
param(
 [Parameter(Mandatory)][ValidateSet('class','class-ai','exam','free','cleanup','browser-cleanup','status','uwf-status','uwf-enable','uwf-disable','uwf-purge-swap','uwf-repair','uwf-reset-stage1','uwf-reset-stage2','windows-update')][string]$Action,
 [switch]$PolicyOnly
)
$ErrorActionPreference='Stop'
if($env:COMPUTERNAME -notmatch '^(?:UEPLV-|LEV-VIGOTSKY-)(0[1-9]|[12][0-9]|3[0-4])$'){throw 'This action helper is only for enrolled UEPLV lab computers.'}
$result=[ordered]@{success=$false;detail=$null;restartRequired=$false;resetPhase=$null;needsUpdateCheck=$false}
$script:CleanupSkippedLinks=[Collections.Generic.List[string]]::new()
$script:CleanupSkippedBusy=[Collections.Generic.List[string]]::new()
$stateRoot=Join-Path $env:ProgramData 'UEPLV\Management'
$reportRoot=Join-Path $env:ProgramData 'UEPLV\Reports'
[IO.Directory]::CreateDirectory($reportRoot)|Out-Null
function Run-Native([string]$File,[string[]]$Arguments,[int[]]$Allowed=@(0)){
 $log=Join-Path $reportRoot ('action-'+$Action+'.log')
 $old=$ErrorActionPreference;try{$ErrorActionPreference='Continue';& $File @Arguments 2>&1|Out-File -LiteralPath $log -Append -Encoding UTF8;$code=$LASTEXITCODE}finally{$ErrorActionPreference=$old}
 if($code -notin $Allowed){throw ([IO.Path]::GetFileName($File)+' returned '+$code+'; see action report.')};return [int]$code
}
function Uwf-State {
 $f=Get-CimInstance -Namespace 'root\standardcimv2\embedded' -ClassName UWF_Filter -ErrorAction Stop
 $v=@(Get-CimInstance -Namespace 'root\standardcimv2\embedded' -ClassName UWF_Volume|Where-Object DriveLetter -eq 'C:')
 $s=@(Get-CimInstance -Namespace 'root\standardcimv2\embedded' -ClassName UWF_Servicing)
 [pscustomobject]@{current=[bool]$f.CurrentEnabled;next=[bool]$f.NextEnabled;currentC=[bool]($v|Where-Object CurrentSession|Select-Object -ExpandProperty Protected);nextC=[bool]($v|Where-Object {-not $_.CurrentSession}|Select-Object -ExpandProperty Protected);servicing=[bool]@($s|Where-Object ServicingEnabled).Count}
}
function Require-Unprotected {
 $f=Get-WindowsOptionalFeature -Online -FeatureName Client-UnifiedWriteFilter
 if($f.State -eq 'DisablePending' -or $f.State -eq 'EnablePending'){throw 'A UWF feature restart is pending. Restart before this action.'}
 if($f.State -eq 'Enabled'){$s=Uwf-State;if($s.current -or $s.next -or $s.servicing){throw 'This action requires UWF disabled now and for the next boot, with servicing off.'}}
}
function Get-Student {
 $account=Get-LocalUser -Name 'LEV VIGOTSKY' -ErrorAction Stop
 $p=Get-CimInstance Win32_UserProfile|Where-Object SID -eq $account.SID.Value|Select-Object -First 1
 if(-not $p){throw 'Student profile has not been created yet. Sign in to LEV VIGOTSKY first.'}
 $root=[IO.Path]::GetFullPath($p.LocalPath).TrimEnd('\')
 if(-not $root.StartsWith(($env:SystemDrive+'\Users\'),[StringComparison]::OrdinalIgnoreCase) -or ($p.Special) -or ((Get-Item -LiteralPath $root -Force).Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Student profile is not an ordinary local user directory.'}
 [pscustomobject]@{Root=$root;Sid=$account.SID.Value}
}
function Ensure-CleanupNative {
 if('UEPLV.CheckedDelete' -as [type]){return}
 Add-Type -TypeDefinition @'
using System;
using System.IO;
using System.Text;
using System.ComponentModel;
using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;
namespace UEPLV {
 public static class CheckedDelete {
  [StructLayout(LayoutKind.Sequential)]struct TagInfo{public uint Attributes;public uint Tag;}
  [StructLayout(LayoutKind.Sequential)]struct Disposition{[MarshalAs(UnmanagedType.U1)]public bool Delete;}
  [StructLayout(LayoutKind.Sequential)]struct BasicInfo{public long Created,Accessed,Written,Changed;public uint Attributes;}
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern SafeFileHandle CreateFile(string p,uint access,uint share,IntPtr security,uint creation,uint flags,IntPtr template);
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern uint GetFinalPathNameByHandle(SafeFileHandle h,StringBuilder p,uint length,uint flags);
  [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetFileInformationByHandleEx(SafeFileHandle h,int kind,out TagInfo info,uint size);
  [DllImport("kernel32.dll",EntryPoint="SetFileInformationByHandle",SetLastError=true)]static extern bool SetDisposition(SafeFileHandle h,int kind,ref Disposition info,uint size);
  [DllImport("kernel32.dll",EntryPoint="SetFileInformationByHandle",SetLastError=true)]static extern bool SetBasic(SafeFileHandle h,int kind,ref BasicInfo info,uint size);
  static void Check(SafeFileHandle h,string root,bool allowRoot){if(h.IsInvalid)throw new Win32Exception(Marshal.GetLastWin32Error(),"Cannot acquire safe cleanup handle");var path=new StringBuilder(32768);uint n=GetFinalPathNameByHandle(h,path,(uint)path.Capacity,0);if(n==0||n>=path.Capacity)throw new Win32Exception(Marshal.GetLastWin32Error(),"Cannot resolve cleanup handle");string resolved=path.ToString();if(resolved.StartsWith(@"\\?\"))resolved=resolved.Substring(4);string expected=Path.GetFullPath(root).TrimEnd('\\');if(!(resolved.StartsWith(expected+"\\",StringComparison.OrdinalIgnoreCase)||(allowRoot&&resolved.Equals(expected,StringComparison.OrdinalIgnoreCase))))throw new IOException("Resolved cleanup handle escaped the approved student root");TagInfo info;if(!GetFileInformationByHandleEx(h,9,out info,8))throw new Win32Exception(Marshal.GetLastWin32Error());if((info.Attributes&0x400)!=0)throw new IOException("Cleanup refused a reparse point");}
  [StructLayout(LayoutKind.Sequential)]struct FileInfo {public uint Attributes;public System.Runtime.InteropServices.ComTypes.FILETIME Created,Accessed,Written;public uint Volume,SizeHigh,SizeLow,Links,IndexHigh,IndexLow;}
  [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetFileInformationByHandle(SafeFileHandle h,out FileInfo info);
  [DefaultDllImportSearchPaths(DllImportSearchPath.System32)][DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl,CharSet=CharSet.Unicode)]static extern int sqlite3_open16(string name,out IntPtr db);
  [DefaultDllImportSearchPaths(DllImportSearchPath.System32)][DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_exec(IntPtr db,byte[] sql,IntPtr callback,IntPtr arg,out IntPtr error);
  [DefaultDllImportSearchPaths(DllImportSearchPath.System32)][DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_close(IntPtr db);
  [DefaultDllImportSearchPaths(DllImportSearchPath.System32)][DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern void sqlite3_free(IntPtr p);
  static SafeFileHandle LockDatabaseFile(string path,string root){var h=CreateFile(path,0xc0000000,3,IntPtr.Zero,4,0x00200000,IntPtr.Zero);try{Check(h,root,false);FileInfo info;if(!GetFileInformationByHandle(h,out info)||info.Links!=1)throw new IOException("Browser database has links or cannot be verified");return h;}catch{h.Dispose();throw;}}
  static void Sql(IntPtr db,string sql){IntPtr error;int code=sqlite3_exec(db,Encoding.UTF8.GetBytes(sql+"\0"),IntPtr.Zero,IntPtr.Zero,out error);if(error!=IntPtr.Zero)sqlite3_free(error);if(code!=0)throw new IOException("Browser history cleanup failed (SQLite "+code+")");}
  public static void FirefoxHistory(string path,string root){
   if(!File.Exists(path))return;
   using(var dbLock=LockDatabaseFile(path,root))using(var walLock=LockDatabaseFile(path+"-wal",root))using(var shmLock=LockDatabaseFile(path+"-shm",root))using(var journalLock=LockDatabaseFile(path+"-journal",root)){
    bool wal=false;using(var header=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite)){header.Position=18;wal=header.ReadByte()==2;}
    IntPtr db=IntPtr.Zero;try{if(sqlite3_open16(path,out db)!=0)throw new IOException("Could not open student browser history");if(!wal)Sql(db,"PRAGMA journal_mode=PERSIST;");Sql(db,"PRAGMA busy_timeout=5000; PRAGMA trusted_schema=OFF; PRAGMA secure_delete=ON; BEGIN IMMEDIATE; DELETE FROM moz_historyvisits; DELETE FROM moz_inputhistory; UPDATE moz_places SET visit_count=0,last_visit_date=NULL,typed=0; COMMIT; PRAGMA wal_checkpoint(TRUNCATE);");}finally{if(db!=IntPtr.Zero)sqlite3_close(db);}
   }
  }
  public static SafeFileHandle LockDirectory(string path,string root){var h=CreateFile(path,0x81,1,IntPtr.Zero,3,0x02200000,IntPtr.Zero);try{Check(h,root,true);return h;}catch{h.Dispose();throw;}}
  public static void Delete(string path,string root,bool directory){using(var h=CreateFile(path,0x10180,7,IntPtr.Zero,3,0x02200000,IntPtr.Zero)){if(h.IsInvalid)throw new Win32Exception(Marshal.GetLastWin32Error(),"Cannot open cleanup item: "+path);Check(h,root,false);if(!directory){var basic=new BasicInfo{Attributes=0x80};if(!SetBasic(h,0,ref basic,(uint)Marshal.SizeOf(typeof(BasicInfo))))throw new Win32Exception(Marshal.GetLastWin32Error());}var d=new Disposition{Delete=true};if(!SetDisposition(h,4,ref d,(uint)Marshal.SizeOf(typeof(Disposition))))throw new Win32Exception(Marshal.GetLastWin32Error(),"Cleanup could not delete the checked item");}}
 }
}
'@
}
function Get-CleanupLease([string]$Path,[string]$AllowedRoot){
 Ensure-CleanupNative
 $full=[IO.Path]::GetFullPath($Path).TrimEnd('\');$root=[IO.Path]::GetFullPath($AllowedRoot).TrimEnd('\')
 if($full -ne $root -and -not $full.StartsWith($root+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Cleanup path escaped the approved student root.'}
 $handles=[Collections.Generic.List[object]]::new()
 try{
  $current=$root;$handles.Add([UEPLV.CheckedDelete]::LockDirectory($current,$root))
  if($full.Length -gt $root.Length){foreach($segment in $full.Substring($root.Length+1).Split('\')){$current=Join-Path $current $segment;$handles.Add([UEPLV.CheckedDelete]::LockDirectory($current,$root))}}
  return ,$handles
 }catch{foreach($h in $handles){$h.Dispose()};throw}
}
function Close-CleanupLease($Lease){if($Lease){foreach($h in $Lease){$h.Dispose()}}}
function Invoke-CheckedCleanupDelete([string]$Path,[string]$Root,[bool]$Directory){
 try{[UEPLV.CheckedDelete]::Delete($Path,$Root,$Directory)}catch{
  $cause=$_.Exception.GetBaseException()
  if($Path -match '\\AppData\\(Local|Roaming)\\' -and $cause -is [ComponentModel.Win32Exception] -and $cause.NativeErrorCode -in @(5,32,33)){
   $script:CleanupSkippedBusy.Add($Path)
  }else{throw}
 }
}
function Clear-CheckedDirectory([string]$Path,[string]$AllowedRoot){
 $full=[IO.Path]::GetFullPath($Path).TrimEnd('\');$allowed=[IO.Path]::GetFullPath($AllowedRoot).TrimEnd('\')
 if(-not $full.StartsWith($allowed+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Cleanup path escaped the approved student area.'}
 if(-not(Test-Path -LiteralPath $full)){return}
 if((Get-Item -LiteralPath $full -Force).Attributes -band [IO.FileAttributes]::ReparsePoint){$script:CleanupSkippedLinks.Add($full);return}
 $lease=Get-CleanupLease $full $AllowedRoot;$directoryHandles=@{}
 try{
  $stack=[Collections.Generic.Stack[string]]::new();$stack.Push($full);$items=[Collections.Generic.List[object]]::new()
  while($stack.Count){$dir=$stack.Pop();foreach($item in Get-ChildItem -LiteralPath $dir -Force){if($item.Attributes -band [IO.FileAttributes]::ReparsePoint){$script:CleanupSkippedLinks.Add($item.FullName);continue};$items.Add($item);if($item.PSIsContainer){$directoryHandles[$item.FullName]=[UEPLV.CheckedDelete]::LockDirectory($item.FullName,$AllowedRoot);$stack.Push($item.FullName)}}}
  foreach($item in @($items|Sort-Object @{Expression={$_.FullName.Length};Descending=$true})){
   if($item.PSIsContainer){$directoryHandles[$item.FullName].Dispose();$directoryHandles.Remove($item.FullName)}
   if($item.PSIsContainer -and @($script:CleanupSkippedLinks|Where-Object {$_.StartsWith($item.FullName+'\',[StringComparison]::OrdinalIgnoreCase)}).Count){continue}
   if($item.PSIsContainer -and @($script:CleanupSkippedBusy|Where-Object {$_.StartsWith($item.FullName+'\',[StringComparison]::OrdinalIgnoreCase)}).Count){continue}
   Invoke-CheckedCleanupDelete $item.FullName $AllowedRoot ([bool]$item.PSIsContainer)
  }
 }finally{foreach($h in $directoryHandles.Values){$h.Dispose()};Close-CleanupLease $lease}
}
function Delete-CheckedFile([string]$Path,[string]$Root){
 $full=[IO.Path]::GetFullPath($Path);$base=[IO.Path]::GetFullPath($Root).TrimEnd('\')
 if(-not $full.StartsWith($base+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Browser cleanup path escaped student profile.'}
 if(Test-Path -LiteralPath $full){$lease=Get-CleanupLease ([IO.Path]::GetDirectoryName($full)) $Root;try{Invoke-CheckedCleanupDelete $full $Root $false}finally{Close-CleanupLease $lease}}
}
