function Set-OwnedRegistryValue([string]$Path,[string]$Name,$Value,[string]$Kind='DWord'){
 $backupPath=Join-Path $stateRoot 'mode-registry-before.json'
 $backup=@();if(Test-Path -LiteralPath $backupPath){$parsed=Get-Content -LiteralPath $backupPath -Raw|ConvertFrom-Json;$backup=@($parsed)}
 if(-not @($backup|Where-Object {$_.path -eq $Path -and $_.name -eq $Name}).Count){$exists=$false;$old=$null;$oldKind=$null;if(Test-Path -LiteralPath $Path){$key=Get-Item -LiteralPath $Path;try{if($key.GetValueNames() -contains $Name){$exists=$true;$old=$key.GetValue($Name);$oldKind=$key.GetValueKind($Name).ToString()}}finally{$key.Close()}};$backup+=@{path=$Path;name=$Name;exists=$exists;value=$old;kind=$oldKind};[IO.File]::WriteAllText($backupPath,(ConvertTo-Json -InputObject @($backup) -Depth 6),[Text.UTF8Encoding]::new($false))}
 if(-not(Test-Path -LiteralPath $Path)){New-Item -Path $Path -Force|Out-Null};New-ItemProperty -LiteralPath $Path -Name $Name -Value $Value -PropertyType $Kind -Force|Out-Null
}
function Restore-OwnedRegistryValue([string]$Path,[string]$Name){
 $backupPath=Join-Path $stateRoot 'mode-registry-before.json';if(-not(Test-Path -LiteralPath $backupPath)){return}
 $records=Get-Content -LiteralPath $backupPath -Raw|ConvertFrom-Json
 $record=$records|Where-Object {$_.path -eq $Path -and $_.name -eq $Name}|Select-Object -First 1
 if(-not $record){return};if($record.exists){if(-not(Test-Path -LiteralPath $Path)){New-Item -Path $Path -Force|Out-Null};New-ItemProperty -LiteralPath $Path -Name $Name -Value $record.value -PropertyType $record.kind -Force|Out-Null}else{Remove-ItemProperty -LiteralPath $Path -Name $Name -ErrorAction SilentlyContinue}
}
function Sync-InstalledUserSettings {
 # Delivered inside the signed action-module update; never read executable code from cloud settings.
 $target=Join-Path $env:ProgramFiles 'UEPLV\Provisioning\Apply-UserSettings.ps1'
 if(-not(Test-Path -LiteralPath (Split-Path $target))){throw 'Installed classroom provisioning folder is missing.'}
 $expected='DF6682485410ED7FEC127794BBF498BE8989A6BA4C29070C6F8C0963894520AC'
 if((Test-Path -LiteralPath $target) -and (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash -eq $expected){return}
 if([IO.File]::Exists($target)){[IO.File]::SetAttributes($target,([IO.File]::GetAttributes($target) -band (-bnot [IO.FileAttributes]::ReadOnly)))}
 [IO.File]::WriteAllBytes($target,[Convert]::FromBase64String(''))
 if((Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash -ne $expected){throw 'Installed user settings failed integrity verification.'}
}
function Sync-StudentDeviceBaseline {
 $target=Join-Path $env:ProgramFiles 'UEPLV\Management\StudentDeviceBaseline.ps1'
 $expected='13DECAFBCF310E4643C327666D1DC5D5BDF3EAEF86B5318D4CA4C2B3A7E8AAE1'
 if(-not(Test-Path $target) -or (Get-FileHash $target).Hash -ne $expected){[IO.File]::WriteAllBytes($target,[Convert]::FromBase64String(''))}
 if((Get-FileHash $target).Hash -ne $expected){throw 'Student baseline module failed integrity verification.'}
 return $target
}
function Reset-StudentBrowserSessions {
 if(-not ('UEPLV.ModeEnforcement.StudentBrowsers' -as [type])){
 Add-Type -ReferencedAssemblies @('System.Management','System.Core') -TypeDefinition @'
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Management;using System.Runtime.InteropServices;namespace UEPLV.ModeEnforcement {
  public static class StudentBrowsers {
    const string Student="LEV VIGOTSKY";
    static readonly string[] Essential={"system","idle","registry","smss","csrss","wininit","winlogon","logonui","services","lsass","svchost","fontdrvhost","dwm","explorer","sihost","taskhostw","ctfmon","conhost","dllhost","runtimebroker","shellexperiencehost","startmenuexperiencehost","searchhost","searchapp","textinputhost","applicationframehost","securityhealthsystray","securityhealthservice","widgets","widgetservice","userinit","rdpclip","audiodg","wudfhost","msedgewebview2"};
    [StructLayout(LayoutKind.Sequential)]struct WtsSession {public int SessionID;public IntPtr Station;public int State;}
    [DllImport("wtsapi32.dll",SetLastError=true)]static extern bool WTSEnumerateSessions(IntPtr server,int reserved,int version,out IntPtr sessions,out int count);
    [DllImport("wtsapi32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool WTSQuerySessionInformation(IntPtr server,int session,int infoClass,out IntPtr buffer,out int bytes);
    [DllImport("wtsapi32.dll")]static extern void WTSFreeMemory(IntPtr buffer);
    static Dictionary<int,string> Sessions(){var result=new Dictionary<int,string>();IntPtr data;int count;if(!WTSEnumerateSessions(IntPtr.Zero,0,1,out data,out count))throw new Exception("Could not enumerate logged-in sessions; no apps were closed");try{int size=Marshal.SizeOf(typeof(WtsSession));for(int i=0;i<count;i++){var s=(WtsSession)Marshal.PtrToStructure(IntPtr.Add(data,i*size),typeof(WtsSession));IntPtr p;int bytes;if(WTSQuerySessionInformation(IntPtr.Zero,s.SessionID,5,out p,out bytes)){try{string user=Marshal.PtrToStringUni(p);if(s.SessionID>0&&string.Equals(user,Student,StringComparison.OrdinalIgnoreCase))result[s.SessionID]=user;}finally{WTSFreeMemory(p);}}}}finally{WTSFreeMemory(data);}return result;}
    static string Owner(int pid){try{using(var p=new ManagementObject("Win32_Process.Handle='"+pid+"'")){using(var owner=p.InvokeMethod("GetOwner",null,null)){return owner!=null&&Convert.ToUInt32(owner["ReturnValue"])==0?Convert.ToString(owner["User"]):null;}}}catch{return null;}}
    static string OwnerSid(int pid){try{using(var p=new ManagementObject("Win32_Process.Handle='"+pid+"'")){using(var owner=p.InvokeMethod("GetOwnerSid",null,null)){return owner!=null&&Convert.ToUInt32(owner["ReturnValue"])==0?Convert.ToString(owner["Sid"]):null;}}}catch{return null;}}
    public static bool SafeToClose(string processName,string fullPath,string owner,string sessionUser,int sessionId){
      if(sessionId<=0||!string.Equals(owner,Student,StringComparison.OrdinalIgnoreCase)||!string.Equals(sessionUser,Student,StringComparison.OrdinalIgnoreCase)||string.IsNullOrEmpty(fullPath))return false;
      string name=(processName??"").ToLowerInvariant();foreach(string files in new[]{Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86)}){if(string.IsNullOrEmpty(files))continue;if(fullPath.StartsWith(Path.Combine(files,"Veyon")+"\\",StringComparison.OrdinalIgnoreCase)||fullPath.StartsWith(Path.Combine(files,"UEPLV")+"\\",StringComparison.OrdinalIgnoreCase))return false;if(Essential.Contains(name)&&(fullPath.StartsWith(Path.Combine(files,"WindowsApps")+"\\",StringComparison.OrdinalIgnoreCase)||fullPath.StartsWith(Path.Combine(files,@"Microsoft\EdgeWebView")+"\\",StringComparison.OrdinalIgnoreCase)))return false;}
      string windows=Environment.GetFolderPath(Environment.SpecialFolder.Windows);if(string.IsNullOrEmpty(windows)||fullPath.StartsWith(windows.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))return false;
      return true;
    }
    public static bool SafeToCloseTaskManager(string name,string path,string owner,string sessionUser,int session){return session>0&&string.Equals(name,"taskmgr",StringComparison.OrdinalIgnoreCase)&&string.Equals(owner,Student,StringComparison.OrdinalIgnoreCase)&&string.Equals(sessionUser,Student,StringComparison.OrdinalIgnoreCase)&&(string.Equals(path,Path.Combine(Environment.SystemDirectory,"Taskmgr.exe"),StringComparison.OrdinalIgnoreCase)||string.Equals(path,Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),@"SysWOW64\Taskmgr.exe"),StringComparison.OrdinalIgnoreCase));}
    public static string Close(string[] onlyNames=null,bool closeTaskManager=false){var sessions=Sessions();if(sessions.Count==0)return "No LEV VIGOTSKY student session is signed in; no apps closed";string localSid=((System.Security.Principal.SecurityIdentifier)new System.Security.Principal.NTAccount(Environment.MachineName,Student).Translate(typeof(System.Security.Principal.SecurityIdentifier))).Value;int closed=0,failed=0,protectedCount=0;var candidates=new List<Process>();
      foreach(var p in Process.GetProcesses()){try{string sessionUser;if(!sessions.TryGetValue(p.SessionId,out sessionUser)||(onlyNames!=null&&!onlyNames.Contains(p.ProcessName,StringComparer.OrdinalIgnoreCase))){p.Dispose();continue;}string path=p.MainModule.FileName;if(OwnerSid(p.Id)!=localSid||!SafeToClose(p.ProcessName,path,Owner(p.Id),sessionUser,p.SessionId)){protectedCount++;p.Dispose();continue;}candidates.Add(p);}catch{p.Dispose();protectedCount++;}}
      foreach(var p in candidates){try{string sessionUser;if(p.HasExited)continue;if(!sessions.TryGetValue(p.SessionId,out sessionUser)||OwnerSid(p.Id)!=localSid||!(SafeToClose(p.ProcessName,p.MainModule.FileName,Owner(p.Id),sessionUser,p.SessionId)||(closeTaskManager&&SafeToCloseTaskManager(p.ProcessName,p.MainModule.FileName,Owner(p.Id),sessionUser,p.SessionId)))){protectedCount++;continue;}bool requested=p.CloseMainWindow();if(requested&&p.WaitForExit(2000)){closed++;continue;}if(!p.HasExited){p.Kill();if(!p.WaitForExit(3000)){failed++;continue;}}closed++;}catch{failed++;}finally{p.Dispose();}}
      string detail="Closed "+closed+" student application processes; "+failed+" could not close. Windows, Veyon, management and staff processes were preserved ("+protectedCount+" protected/skipped). Unsaved student work may be lost.";if(failed>0)throw new Exception(detail);return detail;
    }
    public static string CloseBrowsers(){
      var names=new[]{"msedge","chrome","firefox","brave","opera","opera_gx","chromium","vivaldi","waterfox","librewolf","iexplore"};
      string detail=Close(names);
      var sessions=Sessions();string sid=((System.Security.Principal.SecurityIdentifier)new System.Security.Principal.NTAccount(Environment.MachineName,Student).Translate(typeof(System.Security.Principal.SecurityIdentifier))).Value;
      foreach(var p in Process.GetProcesses())using(p){try{if(!names.Contains(p.ProcessName,StringComparer.OrdinalIgnoreCase)||!sessions.ContainsKey(p.SessionId)||p.HasExited)continue;if(OwnerSid(p.Id)==sid&&!p.HasExited)throw new InvalidOperationException("A student browser is still running; mode switch was not confirmed");}catch(InvalidOperationException){throw;}catch{} }
      return detail;
    }  }

}
'@
 }
 [UEPLV.ModeEnforcement.StudentBrowsers]::CloseBrowsers()
}
function Update-OwnedHosts([string[]]$Domains,[string]$Path=(Join-Path $env:windir 'System32\drivers\etc\hosts')){
 $lines=[Collections.Generic.List[string]]::new()
 for($readAttempt=0;$readAttempt -lt 12;$readAttempt++){
  $input=$null;$reader=$null
  try{
   $input=[IO.File]::Open($path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::ReadWrite)
   $reader=[IO.StreamReader]::new($input,[Text.Encoding]::UTF8,$true)
